int binarySearch(int[] posortowana, int szukana) {
    int lo = 0, hi = posortowana.length - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2; // bezpieczne obliczenie srodka
        if (posortowana[mid] == szukana) {
            return mid;
        } else if (posortowana[mid] < szukana) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1; // nie znaleziono
}

int pierwszeWystapienie(int[] posortowana, int szukana) {
    int lo = 0, hi = posortowana.length - 1, wynik = -1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (posortowana[mid] == szukana) {
            wynik = mid;      // zapamietaj, ale NIE konczy - szukaj wczesniejszego
            hi = mid - 1;
        } else if (posortowana[mid] < szukana) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return wynik;
}

int szukajGranicy_BLAD(int[] tab, int cel) {
    int lo = 0, hi = tab.length - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2; // zaokraglenie W DOL
        if (spelniaWarunek(tab[mid], cel)) {
            hi = mid;
        } else {
            lo = mid; // BLAD: gdy mid==lo, TO SIE NIGDY NIE PRZESUWA - petla wieczna!
        }
    }
    return lo;
}

int szukajGranicy_OK(int[] tab, int cel) {
    int lo = 0, hi = tab.length - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (spelniaWarunek(tab[mid], cel)) {
            hi = mid;
        } else {
            lo = mid + 1; // POPRAWNIE: zawsze przesuwa lo o co najmniej 1
        }
    }
    return lo;
}

